const input = $('Formular Grundeinrichtung').first().json;
const serial = String(input['Seriennummer (leer = alle iPads)'] || '').trim();
if (serial.length > 40 || !/^[A-Za-z0-9]*$/.test(serial)) {
  return [{ json: { ok: false, mode: 'manual', title: 'Nichts eingerichtet', message: 'Die Seriennummer darf nur Buchstaben und Ziffern enthalten.' } }];
}
return [{ json: { ok: true, mode: 'manual', serial } }];

const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (devices.length === 0) return [{ json: { skip: true } }];
return [{ json: { skip: false, serials: devices.map((row) => row.serial_number).filter(Boolean), enrollmentIds: devices.map((row) => row.enrollment_id) } }];

const cfg = $('Konfiguration').first().json;
const message = cfg.serial ? 'Es gibt kein angemeldetes iPad mit der Seriennummer ' + cfg.serial + '.' : 'Es ist noch kein iPad angemeldet.';
return [{ json: { silent: cfg.mode === 'auto', title: 'Nichts eingerichtet', message } }];

const cfg = $('Konfiguration').first().json;
const rows = [...new Map($input.all().map((item) => item.json).filter((row) => row.adam_id).map((row) => [row.adam_id, row])).values()];
const parse = (config) => (typeof config === 'string' ? JSON.parse(config) : (config || {}));
const apps = rows.filter((row) => row.enabled).map((row) => ({ adamId: row.adam_id, name: row.name, bundleId: row.bundle_id, config: parse(row.config) }));
const remove = rows.filter((row) => !row.enabled).map((row) => ({ name: row.name, bundleId: row.bundle_id }));
const missing = cfg.standardBundleIds.filter((id) => !apps.some((app) => app.bundleId === id));
if (missing.length > 0) {
  return [{ json: { ok: false, title: 'Nichts eingerichtet', message: 'Diese Standard-App fehlt im Katalog: ' + missing.join(', ') + '. Bitte zuerst ueber App auf iPads installieren (Andere App) aufnehmen und die Grundeinrichtung erneut starten.' } }];
}
return [{ json: { ok: true, apps, remove } }];

const apps = $('Katalog auswerten').first().json.apps;
const serials = $('Lizenzdaten bauen').first().json.serials;
const res = $input.first().json;
const body = typeof res.body === 'string' ? JSON.parse(res.body || '{}') : (res.body || {});
const known = new Set((body.assets || []).map((asset) => String(asset.adamId)));
if (res.statusCode !== 200) {
  return [{ json: { skip: true, title: 'Nichts eingerichtet', message: 'Die Lizenzliste bei Apple ist nicht abrufbar (HTTP ' + (res.statusCode || res.error || 'keine Antwort') + (body.errorMessage ? ', ' + body.errorMessage : '') + '). Ist das Credential Apple Apps Token gueltig?' } }];
}
const licensed = apps.filter((app) => known.has(app.adamId));
const missing = apps.filter((app) => !known.has(app.adamId));
if (licensed.length === 0) {
  return [{ json: { skip: true, title: 'Nichts eingerichtet', message: 'Diese Apps sind in Apple Business nicht fuer den Standort abgerufen: ' + missing.map((app) => app.name + ' (ID ' + app.adamId + ')').join(', ') + '. Unter Apps und Buecher abrufen, dann die Grundeinrichtung erneut starten.' } }];
}
return [{ json: { skip: false, licensed, missing, body: JSON.stringify({ assets: licensed.map((app) => ({ adamId: app.adamId, pricingParam: 'STDQ' })), serialNumbers: serials }) } }];

const crypto = require('crypto');
const apps = $('Lizenzen pruefen').first().json.licensed;
const remove = $('Katalog auswerten').first().json.remove;
const devices = $('Geraete suchen').all().map((item) => item.json).filter((row) => row.enrollment_id);
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const configXml = (config) => {
  const keys = Object.keys(config || {});
  if (keys.length === 0) return '';
  let xml = '\t\t<key>Configuration</key>\n\t\t<dict>\n';
  for (const key of keys) {
    const value = config[key];
    xml += '\t\t\t<key>' + escapeXml(key) + '</key>\n';
    if (typeof value === 'boolean') xml += '\t\t\t' + (value ? '<true/>' : '<false/>') + '\n';
    else if (typeof value === 'number') xml += '\t\t\t<integer>' + value + '</integer>\n';
    else xml += '\t\t\t<string>' + escapeXml(value) + '</string>\n';
  }
  return xml + '\t\t</dict>\n';
};
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const out = [];
for (const device of devices) {
  for (const app of apps) {
    const commandUuid = crypto.randomUUID();
    const plist = head
      + configXml(app.config)
      + '\t\t<key>ChangeManagementState</key>\n\t\t<string>Managed</string>\n'
      + '\t\t<key>Options</key>\n\t\t<dict>\n\t\t\t<key>PurchaseMethod</key>\n\t\t\t<integer>1</integer>\n\t\t</dict>\n'
      + '\t\t<key>RequestType</key>\n\t\t<string>InstallApplication</string>\n'
      + '\t\t<key>iTunesStoreID</key>\n\t\t<integer>' + Number(app.adamId) + '</integer>\n'
      + tail(commandUuid);
    out.push({ json: { enrollment_id: device.enrollment_id, serial_number: device.serial_number, app: app.name, action: 'install', command_uuid: commandUuid, plist } });
  }
  for (const app of remove) {
    const commandUuid = crypto.randomUUID();
    const plist = head
      + '\t\t<key>Identifier</key>\n\t\t<string>' + escapeXml(app.bundleId) + '</string>\n'
      + '\t\t<key>RequestType</key>\n\t\t<string>RemoveApplication</string>\n'
      + tail(commandUuid);
    out.push({ json: { enrollment_id: device.enrollment_id, serial_number: device.serial_number, app: app.name, action: 'remove', command_uuid: commandUuid, plist } });
  }
}
return out;

const license = $('Lizenz zuweisen').first().json;
const check = $('Lizenzen pruefen').first().json;
const sent = $('App-Befehle bauen').all().map((item) => item.json);
const results = $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  return { serial: source.serial_number || source.enrollment_id, app: source.app, action: source.action, queued, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const failed = results.filter((row) => !row.queued);
const unique = (action) => [...new Set(results.filter((row) => row.action === action).map((row) => row.app))];
const lines = [];
const licenseBody = license.body || {};
if (license.statusCode === 200) {
  lines.push('Lizenz zugewiesen fuer ' + check.licensed.map((app) => app.name).join(', ') + '.');
} else {
  lines.push('ACHTUNG: Die Lizenzzuweisung bei Apple schlug fehl (HTTP ' + (license.statusCode || license.error || 'keine Antwort') + (licenseBody.errorMessage ? ', ' + licenseBody.errorMessage : '') + '). Ohne Lizenz kann ein iPad ohne Apple-ID die App nicht installieren.');
}
lines.push((results.length - failed.length) + ' von ' + results.length + ' App-Befehl(en) eingereiht. Installieren: ' + (unique('install').join(', ') || 'nichts') + '. Entfernen: ' + (unique('remove').join(', ') || 'nichts') + '.');
if (check.missing.length > 0) lines.push('Nicht in Apple Business abgerufen und uebersprungen: ' + check.missing.map((app) => app.name).join(', ') + '.');
if (failed.length > 0) lines.push('Nicht eingereiht: ' + failed.map((row) => row.serial + '/' + row.app + ' (' + row.detail + ')').join(', ') + '.');
const good = license.statusCode === 200 && failed.length === 0 && check.missing.length === 0;
return [{ json: { good, text: lines.join(' ') } }];

const sent = $('Profil-Befehle bauen').all().map((item) => item.json).filter((row) => !row.skip);
return $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  const results = Object.values(body.status || {});
  const pushError = results.map((entry) => entry.push_error).filter(Boolean).join('; ');
  const detail = queued ? pushError : String(response.json.statusCode || response.json.error || 'keine Antwort');
  return { json: { enrollment_id: source.enrollment_id, profile_name: source.profile_name, command_uuid: source.command_uuid, ok: queued ? 'yes' : 'no', detail } };
});

const apps = $('App-Ergebnis auswerten').first().json;
const serials = $('Lizenzdaten bauen').first().json.serials;
const cfg = $('Konfiguration').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
const failed = rows.filter((row) => row.state === 'failed');
const lines = [(cfg.mode === 'auto' ? 'Automatisch fuer neu angemeldete iPads: ' : 'iPads: ') + (serials.join(', ') || 'keine Seriennummer bekannt') + '.'];
lines.push(apps.text);
lines.push(rows.length === 0
  ? 'Hintergrund und Profile wurden nicht gesendet.'
  : 'Hintergrund, Sperrbildschirm-Text (' + cfg.lockScreenText + ') und Erlaubt-Liste: ' + (rows.length - failed.length) + ' von ' + rows.length + ' Befehl(en) eingereiht' + (failed.length > 0 ? ', ' + failed.length + ' fehlgeschlagen' : '') + '.');
lines.push('Alle Apps ausserhalb der Liste werden ausgeblendet. Das wirkt nur auf beaufsichtigten iPads.');
const good = apps.good && failed.length === 0 && rows.length > 0;
return [{ json: { silent: true, title: good ? 'iPad Grundeinrichtung gestartet' : 'iPad Grundeinrichtung mit Problemen', message: lines.join(' '), priority: good ? 'default' : 'high' } }];

let manual = false;
try {
  manual = $('Eingabe pruefen').all().length > 0;
} catch (e) {
  manual = false;
}
return $input.all().map((item) => ({ json: { ...item.json, manual } }));
